import{_t as e,it as t,n,rt as r}from"./chunks/framework.gd_RGE3V.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFlow Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFlow/aireflow-v2-43-0.md","filePath":"aireblock-releases/AireFlow/aireflow-v2-43-0.md","lastUpdated":1794402074000}`),a={name:`aireblock-releases/AireFlow/aireflow-v2-43-0.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="aireflow-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireflow-icon.png"> AireFlow Release Notes</span> <a class="header-anchor" href="#aireflow-release-notes" aria-label="Permalink to “AireFlow Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 2.43.0<br><strong>Release Date:</strong> 18 November 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Dedicated Workflow Pages (FLOW-1279)</li><li>Backwards Paging in the GraphQL API (FLOW-1379)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Accurate API Key Count on Grafana Dashboard (FLOW-1354)</li><li>Right-Click Menu Restored in Code Editors (FLOW-1359)</li><li>Event Engine Connection Errors Resolved (FLOW-1372)</li><li>Secure Handling of Variables and Secrets During Git Import (FLOW-1376)</li></ul><h4 id="🔧-tasks" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks" aria-label="Permalink to “🔧 Tasks”">​</a></h4><ul><li>Faster, Consistent Workflow Definitions List (FLOW-1380)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="dedicated-workflow-pages-flow-1279" tabindex="-1">Dedicated Workflow Pages (FLOW-1279) <a class="header-anchor" href="#dedicated-workflow-pages-flow-1279" aria-label="Permalink to “Dedicated Workflow Pages (FLOW-1279)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Each workflow now has its own dedicated page with a distinct URL, replacing the previous flat accordion layout. The page title and breadcrumb identify the workflow being configured, and a warning is shown before navigating away with unsaved changes.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now focus on one workflow at a time without scrolling through long lists of settings. It is easier to see what your solution is doing at a glance, you can bookmark or share a link straight to a specific workflow, and you are warned before losing any unsaved work.</p></div><h4 id="backwards-paging-in-the-graphql-api-flow-1379" tabindex="-1">Backwards Paging in the GraphQL API (FLOW-1379) <a class="header-anchor" href="#backwards-paging-in-the-graphql-api-flow-1379" aria-label="Permalink to “Backwards Paging in the GraphQL API (FLOW-1379)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Cursor-based paging in the GraphQL API now supports paging backwards as well as forwards, using the standard <code>before</code>, <code>startCursor</code> and <code>hasPreviousPage</code> options.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Applications built on AireFlow can now let you move back to previous pages of results, as well as forward, making it easier to browse through large sets of data.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="accurate-api-key-count-on-grafana-dashboard-flow-1354" tabindex="-1">Accurate API Key Count on Grafana Dashboard (FLOW-1354) <a class="header-anchor" href="#accurate-api-key-count-on-grafana-dashboard-flow-1354" aria-label="Permalink to “Accurate API Key Count on Grafana Dashboard (FLOW-1354)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where the API key metrics shown on the Grafana tenant metrics dashboard did not include all requests made. The count now accurately reflects every API key request across all running instances of the service.</p></div><h4 id="right-click-menu-restored-in-code-editors-flow-1359" tabindex="-1">Right-Click Menu Restored in Code Editors (FLOW-1359) <a class="header-anchor" href="#right-click-menu-restored-in-code-editors-flow-1359" aria-label="Permalink to “Right-Click Menu Restored in Code Editors (FLOW-1359)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where right-clicking inside code and expression editors did not show the context menu. The full menu (including Cut, Copy, Paste and the Command Palette) now appears and works correctly in both single-line and multi-line editors, with keyboard shortcuts unaffected.</p></div><h4 id="event-engine-connection-errors-resolved-flow-1372" tabindex="-1">Event Engine Connection Errors Resolved (FLOW-1372) <a class="header-anchor" href="#event-engine-connection-errors-resolved-flow-1372" aria-label="Permalink to “Event Engine Connection Errors Resolved (FLOW-1372)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Resolved intermittent errors raised by the Event Engine when the service restarts.</p></div><h4 id="secure-handling-of-variables-and-secrets-during-git-import-flow-1376" tabindex="-1">Secure Handling of Variables and Secrets During Git Import (FLOW-1376) <a class="header-anchor" href="#secure-handling-of-variables-and-secrets-during-git-import-flow-1376" aria-label="Permalink to “Secure Handling of Variables and Secrets During Git Import (FLOW-1376)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed a minor security issue in the Git import process.</p></div><h3 id="🔧-tasks-1" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks-1" aria-label="Permalink to “🔧 Tasks”">​</a></h3><hr><h4 id="faster-consistent-workflow-definitions-list-flow-1380" tabindex="-1">Faster, Consistent Workflow Definitions List (FLOW-1380) <a class="header-anchor" href="#faster-consistent-workflow-definitions-list-flow-1380" aria-label="Permalink to “Faster, Consistent Workflow Definitions List (FLOW-1380)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The Workflow Definitions list has been updated to share its data and version management with the new dedicated workflow pages. Changes saved on a workflow page now appear on the list immediately (and vice versa) without a refresh, and data updates no longer collapse expanded rows or reset paging and filtering. This also fixes an issue where enabling a version or toggling debug mode could behave inconsistently.</p></div>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};